// generated by cargo xtask wasm; do not edit (source: crates/pemu-wasm/src/layout.rs)
//
// The raw wasm ABI, as the emulator Worker sees it. Every offset is a byte
// offset into wasm linear memory; every `SIZE` is the size of one record. Cursor cells
// are little-endian `u64` and are read through a `BigUint64Array` view.

/** Value `pemu_abi_version()` must return; a mismatch means the bundle and the core disagree. */
export const ABI_VERSION = 3;

/** Throws when the loaded core does not speak 3. */
export function assertAbiVersion(reported: number): void {
  if (reported !== ABI_VERSION) {
    throw new Error(
      `pemu wasm ABI ${reported} does not match this bundle's ${ABI_VERSION}; rebuild the core and run \`cargo xtask wasm\``,
    );
  }
}

