/** Cells of the cursor block that do not belong to a ring. A ring's head is cell `2 * RingId` and its tail the next cell. */
export const CursorSlot = {
  FrameGeneration: 20,
  AudioOutUnderflows: 21,
  AudioInUnderflows: 22,
  NowPs: 23,
} as const;
export type CursorSlot = (typeof CursorSlot)[keyof typeof CursorSlot];

export const CURSOR_SLOTS = 24;

/** Cell of the cursor block holding the ring's head. */
export function ringHeadSlot(ring: RingId): number {
  return ring * 2;
}

/** Cell of the cursor block holding the ring's tail. */
export function ringTailSlot(ring: RingId): number {
  return ring * 2 + 1;
}

